package com.rpb.reservation.workforce.attendancepolicy;
import static com.rpb.reservation.workforce.attendancepolicy.AttendancePolicyDtos.*;
import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.persistence.WorkforceEmployeeRepository;import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;
import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true) public class AttendancePolicyService {
 private final WorkforceAccess gate;private final WorkforceEmployeeRepository employees;private final AttendancePolicyRepository policies;private final AttendancePolicyResolver resolver;private final WorkforceAudit audit;private final Clock clock;
 public AttendancePolicyService(WorkforceAccess gate,WorkforceEmployeeRepository employees,AttendancePolicyRepository policies,AttendancePolicyResolver resolver,WorkforceAudit audit,Clock clock){this.gate=gate;this.employees=employees;this.policies=policies;this.resolver=resolver;this.audit=audit;this.clock=clock;}
 private LocalDate today(String timezone){return LocalDate.now(clock.withZone(ZoneId.of(timezone)));}
 private WorkforceDtos.Employee employee(CurrentActor actor,UUID store,UUID employee,boolean write){gate.enter(actor,store);var e=employees.find(actor.tenantId(),employee).orElseThrow(WorkforceException::missing);if(!e.storeIds().contains(store))throw WorkforceException.forbidden();if(write||!actor.actorId().equals(e.accountId())){gate.manage(actor,store);if(!gate.managedStores(actor).containsAll(e.storeIds()))throw WorkforceException.forbidden();}return e;}
 public List<PolicyVersion> defaults(CurrentActor actor,UUID store){gate.enter(actor,store);gate.manage(actor,store);policies.store(actor.tenantId(),store);return policies.defaults(actor.tenantId(),store);}
 public PolicyPage self(CurrentActor actor,UUID store){gate.enter(actor,store);return page(actor,store,employees.byAccount(actor.tenantId(),actor.actorId()).orElseThrow(WorkforceException::forbidden).id());}
 public PolicyPage page(CurrentActor actor,UUID store,UUID id){var e=employee(actor,store,id,false);var s=policies.store(actor.tenantId(),store);var date=today(s.timezone());return new PolicyPage(id,gate.managedStores(actor).containsAll(e.storeIds()),date,policies.assignments(actor.tenantId(),id),resolver.resolve(actor.tenantId(),policies.company(actor.tenantId(),id,date),id,date));}
 @Transactional public PolicyVersion saveDefault(CurrentActor actor,UUID store,UUID command,DefaultWrite c){
  gate.sourceWrite(actor);gate.enter(actor,store);gate.manage(actor,store);if(command==null||c==null||c.expectedVersion()==null||c.expectedVersion()<0)throw WorkforceException.invalid();policies.lock(actor.tenantId(),actor.tenantId());var s=policies.store(actor.tenantId(),store);var replay=policies.replay(actor.tenantId(),command,store,null,actor.actorId(),c);if(replay.isPresent())return replay.get();var all=policies.defaults(actor.tenantId(),store);var old=all.isEmpty()?null:all.getLast();if(c.expectedVersion()!=(old==null?0:old.version()))throw WorkforceException.conflict();AttendancePolicyRules.date(c.effectiveFrom(),today(s.timezone()),LocalDate.MIN,old==null?null:old.effectiveFrom());var mode=AttendancePolicyRules.mode(c.mode());var a=AttendancePolicyRules.arrangement(mode,c.arrangement());var next=new PolicyVersion(command,null,s.companyId(),store,c.effectiveFrom(),mode,"store_default",null,0,a,s.timezone(),c.expectedVersion()+1);policies.insert(actor.tenantId(),actor.actorId(),next);policies.receipt(actor.tenantId(),command,store,null,actor.actorId(),c,next);audit.changed(actor,store,"attendance-policy.default",command,old,next);return next;
 }
 @Transactional public PolicyVersion save(CurrentActor actor,UUID store,UUID id,UUID command,AssignmentWrite c){
  gate.sourceWrite(actor);employee(actor,store,id,true);if(command==null||c==null||c.expectedVersion()==null||c.expectedVersion()<0||c.adoptDefault()==null)throw WorkforceException.invalid();policies.lock(actor.tenantId(),actor.tenantId());employees.lock(id);var e=employee(actor,store,id,true);var s=policies.store(actor.tenantId(),store);var replay=policies.replay(actor.tenantId(),command,store,id,actor.actorId(),c);if(replay.isPresent())return replay.get();var all=policies.assignments(actor.tenantId(),id);var old=all.isEmpty()?null:all.getLast();if(c.expectedVersion()!=(old==null?0:old.version()))throw WorkforceException.conflict();AttendancePolicyRules.date(c.effectiveFrom(),today(s.timezone()),e.hireDate(),old==null?null:old.effectiveFrom());if(e.leaveDate()!=null&&c.effectiveFrom().isAfter(e.leaveDate()))throw WorkforceException.invalid();if(!s.companyId().equals(policies.company(actor.tenantId(),id,c.effectiveFrom())))throw WorkforceException.invalid();
  PolicyVersion d=null;String mode;Arrangement a;String timezone=s.timezone();
  if(c.adoptDefault()){if(c.defaultId()==null||c.mode()!=null||c.arrangement()!=null)throw WorkforceException.invalid();d=policies.find(actor.tenantId(),c.defaultId()).orElseThrow(WorkforceException::missing);if(d.employeeId()!=null||!d.sourceStoreId().equals(store)||!d.companyId().equals(s.companyId())||d.effectiveFrom().isAfter(c.effectiveFrom()))throw WorkforceException.invalid();mode=d.mode();a=d.arrangement();timezone=d.timezone();}else{if(c.defaultId()!=null)throw WorkforceException.invalid();mode=AttendancePolicyRules.mode(c.mode());a=AttendancePolicyRules.arrangement(mode,c.arrangement());}
  var next=new PolicyVersion(command,id,s.companyId(),store,c.effectiveFrom(),mode,d==null?"personal":"adopted_default",d==null?null:d.id(),d==null?0:d.version(),a,timezone,c.expectedVersion()+1);policies.insert(actor.tenantId(),actor.actorId(),next);policies.receipt(actor.tenantId(),command,store,id,actor.actorId(),c,next);audit.changed(actor,store,"attendance-policy.employee",command,old,next);return next;
 }
}
